// Hier stehen die Quellen. Neue Quelle = neue Zeile.
const quellen = [
  { quelle: 'Tagesschau Wirtschaft', url: 'https://www.tagesschau.de/wirtschaft/index~rss2.xml' },
  { quelle: 'Tagesschau Finanzen',   url: 'https://www.tagesschau.de/wirtschaft/finanzen/index~rss2.xml' },
  { quelle: 'Handelsblatt Finanzen', url: 'https://www.handelsblatt.com/contentexport/feed/finanzen' },
  { quelle: 'EZB (englisch)',        url: 'https://www.ecb.europa.eu/rss/press.html' },
];
return quellen.map(q => ({ json: q }));

// Behält nur Meldungen der letzten 24 Stunden und wirft doppelte Titel raus.
const grenze = Date.now() - 24 * 60 * 60 * 1000;
const gesehen = new Set();
const raus = [];
for (const item of $input.all()) {
  const n = item.json;
  if (!n.title || !n.link) continue;
  // Tagesschau-Videos haben keinen Text – daraus würde die KI nur raten
  if (/tagesschau\.de\/(video|multimedia)\//.test(n.link)) continue;
  const zeit = Date.parse(n.isoDate || n.pubDate || '');
  if (zeit && zeit < grenze) continue;
  const schluessel = n.title.trim().toLowerCase();
  if (gesehen.has(schluessel)) continue;
  gesehen.add(schluessel);
  raus.push({ json: { titel: n.title.trim(), link: n.link, zeit: zeit || null, text: (n.contentSnippet || '').trim() } });
}
return raus;

// Baut aus allen Meldungen EINE Markdown-Notiz fürs Vault – die besten Video-Ideen zuerst.
const heute = $now.setZone('Europe/Berlin');
const quelleVon = link => {
  const h = (link.match(/^https?:\/\/([^\/]+)/) || [])[1] || link;
  if (h.includes('tagesschau')) return 'Tagesschau';
  if (h.includes('handelsblatt')) return 'Handelsblatt';
  if (h.includes('ecb.europa')) return 'EZB';
  return h;
};
const sterne = n => '★'.repeat(n) + '☆'.repeat(5 - n);
const meldungen = $input.all().map(i => i.json)
  .sort((a, b) => ((b.ki?.potenzial || 0) - (a.ki?.potenzial || 0)) || ((b.zeit || 0) - (a.zeit || 0)));
const mitKi = meldungen.filter(m => m.ki).length;

let md = `---\ntags: [zinsklar, ideen, automatisch]\ndate: ${heute.toFormat('yyyy-MM-dd')}\nquelle: n8n Zinsklar-Ideen-Sammler\n---\n\n# Zinsklar-Ideen ${heute.toFormat('dd.MM.yyyy')}\n\n`;
md += `${meldungen.length} neue Finanz-Meldungen der letzten 24 Stunden, beste Video-Ideen zuerst. Abhaken, was ein Video wert ist.\n\n`;
if (meldungen.length && !mitKi) md += `> [!warning] Die lokale KI war aus – heute nur die Meldungen ohne Video-Ideen.\n> Starten mit: \`systemctl --user start glm-local\`\n\n`;
let abschnitt = null;
for (const m of meldungen) {
  const neu = !m.ki ? 'Ohne KI-Idee' : m.ki.potenzial >= 4 ? 'Top-Ideen' : m.ki.potenzial === 3 ? 'Vielleicht' : 'Eher nicht';
  if (neu !== abschnitt) { md += `\n## ${neu}\n\n`; abschnitt = neu; }
  md += `- [ ] **${m.titel}** (${quelleVon(m.link)}) – [lesen](${m.link})\n`;
  if (m.ki) {
    md += `    - ${sterne(m.ki.potenzial)} **Hook:** „${m.ki.hook}“\n`;
    md += `    - **Idee:** ${m.ki.idee}\n`;
  } else if (m.text) {
    md += `    - ${m.text.slice(0, 200).replace(/\s+/g, ' ')}\n`;
  }
}
if (!meldungen.length) md += '_Heute nichts Neues._\n';
md += `\n---\n_KI-Ideen sind Vorschläge der lokalen KI – vor dem Video Fakten in der Originalmeldung prüfen. Keine Anlageberatung._\n`;
return [{ json: { text: md, dateiname: heute.toFormat('yyyy-MM-dd') + ' Zinsklar-Ideen.md' } }];

// Hängt die KI-Antwort an die passende Meldung. Ist die KI aus, bleibt die Meldung trotzdem drin.
const meldungen = $('Nur neue & ohne Doppelte').all();
const antworten = $input.all();
return meldungen.map((m, i) => {
  let ki = null;
  try {
    const inhalt = antworten[i].json.choices[0].message.content;
    const json = JSON.parse(inhalt.slice(inhalt.indexOf('{'), inhalt.lastIndexOf('}') + 1));
    ki = { hook: String(json.hook || '').trim(), idee: String(json.idee || '').trim(), potenzial: Math.max(1, Math.min(5, Number(json.potenzial) || 1)) };
  } catch (e) { ki = null; }
  return { json: { ...m.json, ki } };
});
